# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.58.0/ankra-cli-darwin-arm64"
      sha256 "c8fbd86f727c3040b9abe153b226fd7bdf9427ec337d6c2a1185fae2654dc00c"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.58.0/ankra-cli-darwin-amd64"
      sha256 "c0f06200eac02f02ffd96b3a72df0b0460776e49ba3ee4fc86e022aaccf08b0d"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.58.0/ankra-cli-linux-arm64"
      sha256 "af586ec2f7f2b060845bd2338bb2fcdfaa47dacdc107d90c8cf2cf20e6ce121b"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.58.0/ankra-cli-linux-amd64"
